26	
27	static std::mutex g_algEnvConfigMutex;
28	static thread_local AlgEnvConfig g_algEnvConfig;
29	
30	std::string GetEnv(std::string IdName)
31	{
32	    constexpr size_t MAX_ENV_VALUE_SIZE = 1024;
33	    char envValue[MAX_ENV_VALUE_SIZE] = {0};
34	    char* mmSysGetEnvValue = envValue;
35	    mmSysGetEnvValue = std::getenv(IdName.c_str());
36	    if (mmSysGetEnvValue != nullptr && mmSysGetEnvValue[0] != '\0') {
37	        return std::string(mmSysGetEnvValue);
38	    } else {
39	        return "EmptyString";
40	    }
41	}
42	
43	static bool IsValidNumberFormat(const std::string& str, const size_t maxDecimal = SIZE_MAX)
44	{
45	    if (str.empty())
46	        return false;
47	
48	    size_t dotPos = str.find('.');
49	    size_t pos = 0;
50	
51	    // 检查小数点前的数字
52	    while (pos < str.length() && pos != dotPos) {
53	        if (!std::isdigit(str[pos]))
54	            return false;
55	        pos++;
56	    }
57	
58	    // 如果有小数点，检查小数部分
59	    if (dotPos != std::string::npos) {
60	        if (dotPos == 0 || dotPos == str.length() - 1)
61	            return false;
62	        size_t decimalLen = str.length() - dotPos - 1;
63	        if (decimalLen > maxDecimal)
64	            return false;
65	
66	        for (size_t i = dotPos + 1; i < str.length(); i++) {
67	            if (!std::isdigit(str[i]))
68	                return false;
69	        }
70	    }
71	
72	    return true;
73	}
74	
75	HcclResult ParseExecTimeout()
76	{
77	    std::string execTimeOutEnv = GetEnv("HCCL_EXEC_TIMEOUT");
78	    if (execTimeOutEnv == "EmptyString") {
79	        g_algEnvConfig.execTimeOutSet = false;
80	        g_algEnvConfig.execTimeout = 0;
81	        return HCCL_SUCCESS;
82	    }
83	
84	    u32 timeoutSize = 2;
85	    if (!IsValidNumberFormat(execTimeOutEnv, timeoutSize)) {
86	        HCCL_WARNING(
87	            "[ParseExecTimeout] HCCL_EXEC_TIMEOUT[%s] format is invalid, use default.", execTimeOutEnv.c_str());
88	        g_algEnvConfig.execTimeOutSet = false;
89	        g_algEnvConfig.execTimeout = 0;
90	        return HCCL_E_PARA;
91	    }
92	
93	    double execTimeOut = 0;
94	    if (SalStrToDouble(execTimeOutEnv, execTimeOut) != HCCL_SUCCESS) {
95	        HCCL_WARNING("[ParseExecTimeout] HCCL_EXEC_TIMEOUT[%s] parse failed, use default.", execTimeOutEnv.c_str());
96	        g_algEnvConfig.execTimeOutSet = false;
97	        g_algEnvConfig.execTimeout = 0;
98	        return HCCL_E_PARA;
99	    }
100	
101	    if (execTimeOut > static_cast<double>(UINT32_MAX)) {
102	        g_algEnvConfig.execTimeOutSet = false;
103	        g_algEnvConfig.execTimeout = 0;
104	        HCCL_WARNING("[ParseExecTimeout] HCCL_EXEC_TIMEOUT[%s] is too large, use default.", execTimeOutEnv.c_str());
105	        return HCCL_E_PARA;
106	    }
107	    g_algEnvConfig.execTimeOutSet = true;
108	    g_algEnvConfig.execTimeout = execTimeOut;
109	    return HCCL_SUCCESS;
110	}
111	
112	bool GetExternalInputExecTimeout(double& execTimeOut)
113	{
114	    std::lock_guard<std::mutex> lock(g_algEnvConfigMutex);
115	    if (!g_algEnvConfig.execTimeOutSet) {
116	        return false;
117	    }
118	
119	    execTimeOut = g_algEnvConfig.execTimeout;
120	    return true;
121	}
122	
123	HcclResult ParseMultipleDimensionSplitRatio()
124	{
125	    const char* multipleDimensionSplitRatioEnv = std::getenv("HCCL_ALG_MULTIPLE_DIMENSION_SPLIT_RATIO");
126	    if (multipleDimensionSplitRatioEnv == nullptr) {
127	        g_algEnvConfig.multipleDimensionSplitRatioSet = false;
128	        g_algEnvConfig.multipleDimensionSplitRatio = 0;
129	        return HCCL_SUCCESS;
130	    }
131	
132	    std::string multipleDimensionSplitRatioStr(multipleDimensionSplitRatioEnv);
133	    if (!IsValidNumberFormat(multipleDimensionSplitRatioStr)) {
134	        HCCL_WARNING(
135	            "[ParseMultipleDimensionSplitRatio] HCCL_ALG_MULTIPLE_DIMENSION_SPLIT_RATIO[%s] format is invalid, use "
136	            "default.",
137	            multipleDimensionSplitRatioStr.c_str());
138	        g_algEnvConfig.multipleDimensionSplitRatioSet = false;
139	        g_algEnvConfig.multipleDimensionSplitRatio = 0;
140	        return HCCL_E_PARA;
141	    }
142	
143	    double multipleDimensionSplitRatio = 0;
144	    if (SalStrToDouble(multipleDimensionSplitRatioStr, multipleDimensionSplitRatio) != HCCL_SUCCESS) {
145	        HCCL_WARNING(
146	            "[ParseMultipleDimensionSplitRatio] HCCL_ALG_MULTIPLE_DIMENSION_SPLIT_RATIO[%s] parse failed, use default.",
147	            multipleDimensionSplitRatioStr.c_str());
148	        g_algEnvConfig.multipleDimensionSplitRatioSet = false;
149	        g_algEnvConfig.multipleDimensionSplitRatio = 0;
150	        return HCCL_E_PARA;
151	    }
152	
153	    g_algEnvConfig.multipleDimensionSplitRatioSet = true;
154	    g_algEnvConfig.multipleDimensionSplitRatio = multipleDimensionSplitRatio;
155	    return HCCL_SUCCESS;
156	}
157	
158	bool GetExternalInputMultipleDimensionSplitRatio(double& multipleDimensionSplitRatio)
159	{
160	    std::lock_guard<std::mutex> lock(g_algEnvConfigMutex);
161	    if (!g_algEnvConfig.multipleDimensionSplitRatioSet) {
162	        return false;
163	    }
164	
165	    multipleDimensionSplitRatio = g_algEnvConfig.multipleDimensionSplitRatio;
166	    return true;
167	}
168	
169	bool GetExternalInputTaskExceptionEnable()
170	{
171	    std::lock_guard<std::mutex> lock(g_algEnvConfigMutex);
172	    return g_algEnvConfig.taskExceptionEnable;
173	}
174	
175	/* 入口 */
176	HcclResult InitEnvConfig()
177	{
178	    std::lock_guard<std::mutex> lock(g_algEnvConfigMutex);
179	    // 解析算子展开模式
180	    HcclResult ret = ParseOpExpansion();
181	    RPT_ENV_ERR(
182	        ret != HCCL_SUCCESS, "EI0001", std::vector<std::string>({"value", "env", "expect"}),
183	        std::vector<std::string>({GetEnv("HCCL_OP_EXPANSION_MODE"), "HCCL_OP_EXPANSION_MODE", "should be \"AI_CPU\""}));
184	    CHK_PRT_RET(
185	        ret != HCCL_SUCCESS,
186	        HCCL_ERROR(
187	            "[Init][EnvVarParam]errNo[0x%016llx] In init env variable param, parse "
188	            "HCCL_OP_EXPANSION_MODE failed. errorno[%d]",
