411	HcclResult SetSpecificAlgType(std::vector<std::string>& algos)
412	{
413	    for (std::string& algConfig : algos) {
414	        std::size_t found = algConfig.find("=");
415	        std::string opStringName = algConfig.substr(0, found);
416	        if (opStringName == "others") {
417	            std::vector<HcclAlgoType> algType;
418	            std::string remainAlgoConfig = algConfig.substr(found + 1);
419	            CHK_RET(ParseAlgoString("others op type", remainAlgoConfig, algType));
420	            for (u32 opType = 0; opType < static_cast<u32>(HcclCMDType::HCCL_CMD_MAX); opType++) {
421	                g_algEnvConfig.hcclAlgoConfig[static_cast<HcclCMDType>(opType)] = algType;
422	            }
423	        }
424	    }
425	    std::map<std::string, HcclCMDType> hcclOpTypeMap = {
426	        {"broadcast", HcclCMDType::HCCL_CMD_BROADCAST},
427	        {"allreduce", HcclCMDType::HCCL_CMD_ALLREDUCE},
428	        {"reduce", HcclCMDType::HCCL_CMD_REDUCE},
429	        {"send", HcclCMDType::HCCL_CMD_SEND},
430	        {"receive", HcclCMDType::HCCL_CMD_RECEIVE},
431	        {"allgather", HcclCMDType::HCCL_CMD_ALLGATHER},
432	        {"reducescatter", HcclCMDType::HCCL_CMD_REDUCE_SCATTER},
433	        {"alltoall", HcclCMDType::HCCL_CMD_ALLTOALL},
434	        {"gather", HcclCMDType::HCCL_CMD_GATHER},
435	        {"scatter", HcclCMDType::HCCL_CMD_SCATTER},
436	        {"sendrecv", HcclCMDType::HCCL_CMD_BATCH_SEND_RECV},
437	    };
438	    for (std::string& algConfig : algos) {
439	        std::size_t found = algConfig.find("=");
440	        std::string opStringName = algConfig.substr(0, found);
441	        if (hcclOpTypeMap.find(opStringName) != hcclOpTypeMap.end()) {
442	            HcclCMDType optype = hcclOpTypeMap[opStringName];
443	            std::string remainAlgoConfig = algConfig.substr(found + 1);
444	            std::vector<HcclAlgoType> algType;
445	            CHK_RET(ParseAlgoString(opStringName, remainAlgoConfig, algType));
446	            if (algType[0] == HcclAlgoType::HCCL_ALGO_TYPE_NULL) {
447	                HCCL_ERROR("[SetSpecificAlgType] specific config level0 not support null type.");
448	                return HCCL_E_PARA;
449	            }
450	            g_algEnvConfig.hcclAlgoConfig[optype] = algType;
451	        } else {
452	            HCCL_ERROR(
453	                "[SetSpecificAlgType] specific config optype[%s] is invalid, please check", opStringName.c_str());
454	            return HCCL_E_PARA;
455	        }
456	    }
457	    g_algEnvConfig.hcclAlgoConfig[HcclCMDType::HCCL_CMD_ALLTOALLV]
458	        = g_algEnvConfig.hcclAlgoConfig[HcclCMDType::HCCL_CMD_ALLTOALL];
459	    g_algEnvConfig.hcclAlgoConfig[HcclCMDType::HCCL_CMD_ALLTOALLVC]
460	        = g_algEnvConfig.hcclAlgoConfig[HcclCMDType::HCCL_CMD_ALLTOALL];
461	    return HCCL_SUCCESS;
462	}
