464	HcclResult ParserHcclAlgoLevel(const std::string& algoLevel, u32& level, HcclAlgoType& algoType)
465	{
466	    std::size_t found = algoLevel.find(":");
467	    if ((found == 0) || (found == (algoLevel.length() - 1))) {
468	        HCCL_ERROR("[Parser][HcclAlgoLevel] algo config is invalid.");
469	        return HCCL_E_PARA;
470	    }
471	
472	    std::string orginalLevel = algoLevel.substr(0, found);
473	    std::string orginalAlgo = algoLevel.substr(found + 1);
474	
475	    const std::map<std::string, u32> hcclAlgoLevelMap
476	        = {{"level0", HCCL_ALGO_LEVEL_0},
477	           {"level1", HCCL_ALGO_LEVEL_1},
478	           {"level2", HCCL_ALGO_LEVEL_2},
479	           {"level3", HCCL_ALGO_LEVEL_3}};
480	
481	    const std::map<std::string, HcclAlgoType> hcclAlgoTypeMap = {
482	        {"null", HcclAlgoType::HCCL_ALGO_TYPE_NULL},
483	        {"ring", HcclAlgoType::HCCL_ALGO_TYPE_RING},
484	        {"pipeline", HcclAlgoType::HCCL_ALGO_TYPE_PIPELINE},
485	        {"fullmesh", HcclAlgoType::HCCL_ALGO_TYPE_FULLMESH},
486	        {"H-D_R", HcclAlgoType::HCCL_ALGO_TYPE_HDR},
487	        {"pairwise", HcclAlgoType::HCCL_ALGO_TYPE_PAIRWISE},
488	        {"NHR", HcclAlgoType::HCCL_ALGO_TYPE_NHR},
489	        {"NHR_V1", HcclAlgoType::HCCL_ALGO_TYPE_NHR_V1},
490	        {"AHC", HcclAlgoType::HCCL_ALGO_TYPE_AHC},
491	        {"AHC_BROKE", HcclAlgoType::HCCL_ALGO_TYPE_AHC_BROKE},
492	        {"NB", HcclAlgoType::HCCL_ALGO_TYPE_NB},
493	        {"NA", HcclAlgoType::HCCL_ALGO_TYPE_NA},
494	    };
495	
496	    auto iterAlgoLevel = hcclAlgoLevelMap.find(orginalLevel);
497	    if (iterAlgoLevel == hcclAlgoLevelMap.end()) {
498	        HCCL_ERROR("[Parser][HcclAlgoLevel] algo config is invalid, level %s is not supported.", orginalLevel.c_str());
499	        return HCCL_E_PARA;
500	    }
501	
502	    auto iterAlgoType = hcclAlgoTypeMap.find(orginalAlgo);
503	    if (iterAlgoType == hcclAlgoTypeMap.end()) {
504	        HCCL_ERROR("[Parser][HcclAlgoLevel] algo config is invalid, algo %s is not supported.", orginalAlgo.c_str());
505	        return HCCL_E_PARA;
506	    }
507	
508	    level = iterAlgoLevel->second;
509	    algoType = iterAlgoType->second;
510	
511	    return HCCL_SUCCESS;
512	}
