514	HcclResult ParseAlgoString(std::string opName, std::string& algoString, std::vector<HcclAlgoType>& algType)
515	{
516	    algType = std::vector<HcclAlgoType>(HCCL_ALGO_LEVEL_NUM, HcclAlgoType::HCCL_ALGO_TYPE_DEFAULT);
517	    std::vector<std::string> algoLevels;
518	    HcclResult ret = SplitHcclAlgoLevel(algoString, algoLevels);
519	    CHK_PRT_RET(
520	        ret != HCCL_SUCCESS,
521	        HCCL_ERROR(
522	            "[Set][HcclAlgoConfig]hccl algo config[%s] is invalid. "
523	            "expect: level0:NA;level1:<algo> or <op0>=level0:NA;level1:<algo0>/<op1>=level0:NA;level1:<algo1>",
524	            algoString.c_str()),
525	        ret);
526	    for (auto algoLevel : algoLevels) {
527	        u32 level = 0;
528	        HcclAlgoType algo = HcclAlgoType::HCCL_ALGO_TYPE_DEFAULT;
529	        ret = ParserHcclAlgoLevel(algoLevel, level, algo);
530	        CHK_PRT_RET(
531	            ret != HCCL_SUCCESS,
532	            HCCL_ERROR(
533	                "[Set][HcclAlgoConfig]hccl algo config[%s] is invalid. "
534	                "expect: level0:NA;level1:<algo> or <op0>=level0:NA;level1:<algo0>/<op1>=level0:NA;level1:<algo1>",
535	                algoString.c_str()),
536	            ret);
537	        // 检查是否存在重复配置level
538	        if (algType[level] != HcclAlgoType::HCCL_ALGO_TYPE_DEFAULT) {
539	            HCCL_ERROR(
540	                "[Set][HcclAlgoConfig]hccl algo config[%s] is invalid. "
541	                "expect: level0:NA;level1:<algo> or <op0>=level0:NA;level1:<algo0>/<op1>=level0:NA;level1:<algo1>",
542	                algoString.c_str());
543	            return HCCL_E_PARA;
544	        }
545	        algType[level] = algo;
546	    }
547	    auto level0Iter = HcclAlgoTypeMap.find(algType[HCCL_ALGO_LEVEL_0]);
548	    auto level1Iter = HcclAlgoTypeMap.find(algType[HCCL_ALGO_LEVEL_1]);
549	    auto level2Iter = HcclAlgoTypeMap.find(algType[HCCL_ALGO_LEVEL_2]);
550	    auto level3Iter = HcclAlgoTypeMap.find(algType[HCCL_ALGO_LEVEL_3]);
551	    HCCL_INFO(
552	        "hccl algo op %s config: config level0:%s, level1:%s, level2:%s, level3:%s", opName.c_str(),
553	        level0Iter->second.c_str(), level1Iter->second.c_str(), level2Iter->second.c_str(), level3Iter->second.c_str());
554	    return HCCL_SUCCESS;
555	}
