557	HcclResult SplitHcclOpType(const std::string& algoConfig, std::vector<std::string>& algos)
558	{
559	    std::string remainAlgoConfig;
560	    std::size_t found = algoConfig.find("/");
561	    if ((found == 0) || (found == (algoConfig.length() - 1))) {
562	        HCCL_ERROR("[Split][SplitHcclOpType] algo config is invalid.");
563	        return HCCL_E_PARA;
564	    } else if (found != std::string::npos) {
565	        remainAlgoConfig = algoConfig.substr(found + 1);
566	    }
567	    algos.push_back(algoConfig.substr(0, found));
568	    if (!remainAlgoConfig.empty()) {
569	        CHK_RET(SplitHcclOpType(remainAlgoConfig, algos));
570	    }
571	    return HCCL_SUCCESS;
572	}
