574	// 新的逐算法的配置和原有的统一配置只可使用一种，发现同时存在时报错
575	HcclResult CheckAlgoConfigValid(std::vector<std::string>& algos, bool& anyCommonConfig, bool& anySpecificConfig)
576	{
577	    for (std::string& algConfig : algos) {
578	        std::size_t found = algConfig.find("=");
579	        if ((found == 0) || (found == (algConfig.length() - 1))) {
580	            HCCL_ERROR("[Split][CheckAlgoConfigValid] algo config is invalid.");
581	            return HCCL_E_PARA;
582	        } else if (found != std::string::npos) {
583	            anySpecificConfig = true;
584	        } else {
585	            anyCommonConfig = true;
586	        }
587	    }
588	    if (anyCommonConfig && anySpecificConfig) {
589	        HCCL_ERROR("[CheckAlgoConfigValid]should not set both algo config way");
590	        return HCCL_E_PARA;
591	    }
592	    if (anyCommonConfig && algos.size() > 1) {
593	        HCCL_ERROR("[CheckAlgoConfigValid]should only set one common config");
594	        return HCCL_E_PARA;
595	    }
596	    return HCCL_SUCCESS;
597	}
598	
599	HcclResult SplitHcclAlgoLevel(const std::string& algoConfig, std::vector<std::string>& algos)
600	{
601	    std::string remainAlgoConfig;
602	    std::size_t found = algoConfig.find(";");
603	    if ((found == 0) || (found == (algoConfig.length() - 1))) {
604	        HCCL_ERROR("[Split][HcclAlgoLevel] algo config is invalid.");
605	        return HCCL_E_PARA;
606	    } else if (found != std::string::npos) {
607	        remainAlgoConfig = algoConfig.substr(found + 1);
608	    } else {
609	        // 最后一组配置,剩余的字符串为空
610	    }
611	    algos.push_back(algoConfig.substr(0, found));
612	
613	    if (algos.size() > HCCL_ALGO_LEVEL_NUM) {
614	        HCCL_ERROR("[Split][HcclAlgoLevel] algo config is invalid. algo level is more than %u.", HCCL_ALGO_LEVEL_NUM);
615	        return HCCL_E_PARA;
616	    }
617	    if (!remainAlgoConfig.empty()) {
618	        CHK_RET(SplitHcclAlgoLevel(remainAlgoConfig, algos));
619	    }
620	
621	    return HCCL_SUCCESS;
622	}
