672	HcclResult ParseIntraLinkType()
673	{
674	    std::string intraPcieEnv = GetEnv("HCCL_INTRA_PCIE_ENABLE");
675	    std::string intraRoceEnv = GetEnv("HCCL_INTRA_ROCE_ENABLE");
676	
677	    u32 intraPcie = 1; // 保存pcie环境变量的解析数字
678	    u32 intraRoce = 0; // 保存roce环境变量的解析数字
679	
680	    // 两个通信域环境变量均未设置，默认走pcie
681	    if (intraPcieEnv == "EmptyString" && intraRoceEnv == "EmptyString") {
682	        HCCL_INFO(
683	            "HCCL_INTRA_PCIE_ENABLE set by default to [%u], HCCL_INTRA_ROCE_ENABLE set by default to [%u]", intraPcie,
684	            intraRoce);
685	        return HCCL_SUCCESS;
686	    }
687	
688	    if (intraPcieEnv != "EmptyString") { // 解析HCCL_INTRA_PCIE_ENABLE为数字
689	        // 校验环境变量长度
690	        bool isEnvLenValid = CheckEnvLen(intraPcieEnv.c_str(), MAX_LEN_OF_DIGIT_ENV);
691	        CHK_PRT_RET(
692	            !isEnvLenValid,
693	            HCCL_ERROR(
694	                "[Parse][IntraLinkType]errNo[0x%016llx] Invalid INTRA_PCIE_ENABLE env len, len is bigger than "
695	                "[%u]. errorno[%d]",
696	                HCCL_ERROR_CODE(HCCL_E_PARA), MAX_LEN_OF_DIGIT_ENV, HCCL_E_PARA),
697	            HCCL_E_PARA);
698	        std::string intraPcieStr(intraPcieEnv);
699	        CHK_RET(GetIntraLinkTypeDigit(intraPcieStr, intraPcie));
700	    }
701	
702	    if (intraRoceEnv != "EmptyString") { // 解析HCCL_INTRA_ROCE_ENABLE为数字
703	        // 校验环境变量长度
704	        bool isEnvLenValid = CheckEnvLen(intraRoceEnv.c_str(), MAX_LEN_OF_DIGIT_ENV);
705	        CHK_PRT_RET(
706	            !isEnvLenValid,
707	            HCCL_ERROR(
708	                "[Parse][IntraLinkType]errNo[0x%016llx] Invalid INTRA_ROCE_ENABLE env len, len is bigger than "
709	                "[%u]. errorno[%d]",
710	                HCCL_ERROR_CODE(HCCL_E_PARA), MAX_LEN_OF_DIGIT_ENV, HCCL_E_PARA),
711	            HCCL_E_PARA);
712	        std::string intraRoceStr(intraRoceEnv);
713	        CHK_RET(GetIntraLinkTypeDigit(intraRoceStr, intraRoce));
714	    }
715	
716	    // 只配置了roce的环境变量
717	    if (intraPcieEnv == "EmptyString" && intraRoceEnv != "EmptyString") {
718	        if (intraRoce == 0) { // roce环境变量值为0，报错
719	            HCCL_ERROR("[Parse][IntraLinkType]only set HCCL_INTRA_ROCE_ENABLE, and the val is zero, pls set "
720	                       "HCCL_INTRA_PCIE_ENABLE");
721	            return HCCL_E_PARA;
722	        } else { // roce环境变量值为1，走roce
723	            intraPcie = 0;
724	        }
725	        HCCL_INFO(
726	            "HCCL_INTRA_PCIE_ENABLE set by environment to [%u], "
727	            "HCCL_INTRA_ROCE_ENABLE set by environment to [%u]",
728	            intraPcie, intraRoce);
729	    }
730	
731	    // 只配置了pcie的环境变量
732	    if (intraPcieEnv != "EmptyString" && intraRoceEnv == "EmptyString") {
733	        if (intraPcie == 0) { // pcie环境变量值为0，报错
734	            HCCL_ERROR("[Parse][IntraLinkType]only set HCCL_INTRA_PCIE_ENABLE, and the val is zero, pls set "
735	                       "HCCL_INTRA_ROCE_ENABLE");
736	            return HCCL_E_PARA;
737	        }
738	        HCCL_INFO(
739	            "HCCL_INTRA_PCIE_ENABLE set by environment to [%u], "
740	            "HCCL_INTRA_ROCE_ENABLE set by default to [%u]",
741	            intraPcie, intraRoce);
742	    }
743	
744	    // pcie和roce环境变量同时配置且不相等
745	    if (intraPcieEnv != "EmptyString" && intraRoceEnv != "EmptyString") {
746	        if ((intraPcie == 0 && intraRoce == 1) || (intraPcie == 1 && intraRoce == 0)) {
747	            HCCL_INFO(
748	                "HCCL_INTRA_PCIE_ENABLE set by environment to [%u], "
749	                "HCCL_INTRA_ROCE_ENABLE set by environment to [%u]",
750	                intraPcie, intraRoce);
751	        }
752	    }
753	
754	    // pcie和roce环境变量同时配置且相等
755	    if ((intraPcie ^ intraRoce) == 0) {
756	        if (intraPcie == 1) { // 同时为1，暂不支持，报错
757	            HCCL_ERROR(
758	                "[Parse][IntraLinkType] Enabling intra Pcie and intra Roce at the same time is not supported now.");
759	            return HCCL_E_PARA;
760	        } else { // 同时为0，走pcie
761	            HCCL_WARNING("Pcie and Roce Env both set to zero at the same time, intra comm is default Pcie");
762	            intraPcie = 1;
763	        }
764	        HCCL_INFO(
765	            "HCCL_INTRA_PCIE_ENABLE set by environment to [%u], "
766	            "HCCL_INTRA_ROCE_ENABLE set by environment to [%u]",
767	            intraPcie, intraRoce);
768	    }
769	
770	    g_algEnvConfig.intraRoceSwitch = intraRoce;
771	    return HCCL_SUCCESS;
772	}
