796	HcclResult ParseOpExpansion()
797	{
798	    const std::string& opExpansionModeEnv = GetEnv("HCCL_OP_EXPANSION_MODE");
799	    g_algEnvConfig.aicpuUnfold = false;
800	    g_algEnvConfig.aivMode = false;
801	    g_algEnvConfig.aivOnlyMode = false;
802	    g_algEnvConfig.ccuMSMode = false;
803	    g_algEnvConfig.ccuSchedMode = false;
804	
805	    if (opExpansionModeEnv == "CCU_MS") {
806	        g_algEnvConfig.ccuMSMode = true;
807	        return HCCL_SUCCESS;
808	    }
809	
810	    if (opExpansionModeEnv == "CCU_SCHED") {
811	        g_algEnvConfig.ccuSchedMode = true;
812	        return HCCL_SUCCESS;
813	    }
814	
815	    HcclDevType deviceType;
816	    CHK_RET(HcclGetDeviceType(deviceType));
817	    // 910_93默认打开AICPU展开
818	    if (deviceType == HcclDevType::DEV_TYPE_910_93) {
819	        g_algEnvConfig.aicpuUnfold = true;
820	    }
821	
822	    if (opExpansionModeEnv == "EmptyString") {
823	        HCCL_INFO(
824	            "HCCL_OP_EXPANSION_MODE is not set, aicpuUnfold is [%u], aivMode is [%u]", g_algEnvConfig.aicpuUnfold,
825	            g_algEnvConfig.aivMode);
826	        return HCCL_SUCCESS;
827	    }
828	
829	    if (opExpansionModeEnv == "AI_CPU" || opExpansionModeEnv == "AICPU_TS") {
830	        if (deviceType == HcclDevType::DEV_TYPE_910) {
831	            HCCL_WARNING("910 do not support AICPU unfold.");
832	        } else {
833	            g_algEnvConfig.aicpuUnfold = true;
834	        }
835	
836	        // A5默认开启aicpu task cache
837	        if (deviceType == HcclDevType::DEV_TYPE_950) {
838	            g_algEnvConfig.aicpuCacheEnable = 1;
839	        }
840	    } else if (opExpansionModeEnv == "AIV") {
841	        if (g_algEnvConfig.hcclDeterministic == true) {
842	            HCCL_WARNING("Deterministic do not support aiv");
843	        }
844	        g_algEnvConfig.aivMode = true;
845	    } else if (opExpansionModeEnv == "HOST") {
846	        g_algEnvConfig.aivMode = false;
847	        g_algEnvConfig.aicpuUnfold = false;
848	    } else if (opExpansionModeEnv == "HOST_TS") {
849	        if (deviceType == HcclDevType::DEV_TYPE_910B) {
850	            g_algEnvConfig.enableFfts = false;
851	        } else {
852	            HCCL_WARNING("deviceType[%u] do not support HOST_TS", deviceType);
853	        }
854	    } else if (opExpansionModeEnv == "AICPU_CacheDisable") {
855	        if (deviceType == HcclDevType::DEV_TYPE_910) {
856	            HCCL_WARNING("910 do not support AICPU unfold.");
857	        } else {
858	            g_algEnvConfig.aicpuUnfold = true;
859	            g_algEnvConfig.aicpuCacheEnable = 0; // Disable aicpu cache
860	        }
861	    } else {
862	        HCCL_ERROR(
863	            "HCCL_OP_EXPANSION_MODE is set to [%s], which is incorrect. Please check", opExpansionModeEnv.c_str());
864	        return HCCL_E_PARA;
865	    }
866	    HCCL_INFO(
867	        "environmental variable HCCL_OP_EXPANSION_MODE is [%s], aicpuUnfold[%u], aicpuCacheEnable[%u], "
868	        "aivMode[%u], enableFfts[%u]",
869	        opExpansionModeEnv.c_str(), g_algEnvConfig.aicpuUnfold, g_algEnvConfig.aicpuCacheEnable, g_algEnvConfig.aivMode,
870	        g_algEnvConfig.enableFfts);
871	    return HCCL_SUCCESS;
872	}
