874	HcclResult SplitHcclRetryEnable(const std::string& retryConfig, std::vector<std::string>& retryEnables)
875	{
876	    std::string remainRetryConfig;
877	    std::size_t found = retryConfig.find(",");
878	    if ((found == 0) || (found == (retryConfig.length() - 1))) {
879	        HCCL_ERROR("[SplitHcclRetryEnable] algo config is invalid.");
880	        return HCCL_E_PARA;
881	    } else if (found != std::string::npos) {
882	        remainRetryConfig = retryConfig.substr(found + 1);
883	    } else {
884	        // 最后一组配置,剩余的字符串为空
885	    }
886	    retryEnables.push_back(retryConfig.substr(0, found));
887	
888	    if (retryEnables.size() > HCCL_RETRY_ENABLE_LEVEL_NUM) {
889	        HCCL_ERROR(
890	            "[SplitHcclRetryEnable] retryEnable config is invalid. retryEnable level is more than %u.",
891	            HCCL_RETRY_ENABLE_LEVEL_NUM);
892	        return HCCL_E_PARA;
893	    }
894	    if (!remainRetryConfig.empty()) {
895	        CHK_RET(SplitHcclRetryEnable(remainRetryConfig, retryEnables));
896	    }
897	    return HCCL_SUCCESS;
898	}
