900	HcclResult CollectRetryEnableFromConfig(const std::vector<std::string>& retryEnables)
901	{
902	    const std::map<std::string, u32> hcclRetryLevelMap
903	        = {{"L0", HCCL_RETRY_ENABLE_LEVEL_0}, {"L1", HCCL_RETRY_ENABLE_LEVEL_1}, {"L2", HCCL_RETRY_ENABLE_LEVEL_2}};
904	
905	    std::map<std::string, u32> countHcclRetryLevelMap = {{"L0", 0}, {"L1", 0}, {"L2", 0}};
906	
907	    const std::map<std::string, bool> hcclRetryEnableMap = {{"0", false}, {"1", true}};
908	    for (auto retryEnableLevel : retryEnables) {
909	        u32 level = 0;
910	        bool retryEnable = false;
911	        std::size_t found = retryEnableLevel.find(":");
912	        if ((found == 0) || (found == (retryEnableLevel.length() - 1))) {
913	            HCCL_ERROR("[CollectRetryEnableFromConfig] Hccl retryEnableLevel is invalid.");
914	            return HCCL_E_PARA;
915	        }
916	        std::string orginalLevel = retryEnableLevel.substr(0, found);
917	        std::string orginalRetryEnable = retryEnableLevel.substr(found + 1);
918	        if (orginalLevel == "L0") {
919	            HCCL_RUN_WARNING("[CollectRetryEnableFromConfig] L0 config does not take effect");
920	        }
921	        // 检查是否存在重复配置level
922	        auto iterCountRetryLevel = countHcclRetryLevelMap.find(orginalLevel);
923	        if (iterCountRetryLevel == countHcclRetryLevelMap.end()) {
924	            HCCL_ERROR(
925	                "[CollectRetryEnableFromConfig] Retry config is invalid, level %s is not supported.",
926	                orginalLevel.c_str());
927	            return HCCL_E_PARA;
928	        }
929	        if (countHcclRetryLevelMap[orginalLevel] == 1) {
930	            HCCL_ERROR(
931	                "[CollectRetryEnableFromConfig] Retry config level[%s] is repeated, expect: L1:0, L2:0",
932	                orginalLevel.c_str());
933	            return HCCL_E_PARA;
934	        }
935	        countHcclRetryLevelMap[orginalLevel] += 1;
936	        // 获取level和对应的retryEnable，并赋值给g_algEnvConfig.hcclRetryConfig
937	        auto iterRetryLevel = hcclRetryLevelMap.find(orginalLevel);
938	        if (iterRetryLevel == hcclRetryLevelMap.end()) {
939	            HCCL_ERROR(
940	                "[CollectRetryEnableFromConfig] Retry config is invalid, level %s is not supported.",
941	                orginalLevel.c_str());
942	            return HCCL_E_PARA;
943	        }
944	        auto iterRetryEnable = hcclRetryEnableMap.find(orginalRetryEnable);
945	        if (iterRetryEnable == hcclRetryEnableMap.end()) {
946	            HCCL_ERROR(
947	                "[CollectRetryEnableFromConfig] Retry config is invalid, retryEnable %s is not supported.",
948	                orginalRetryEnable.c_str());
949	            return HCCL_E_PARA;
950	        }
951	        level = iterRetryLevel->second;
952	        retryEnable = iterRetryEnable->second;
953	        g_algEnvConfig.hcclRetryConfig[level] = retryEnable;
954	    }
955	    return HCCL_SUCCESS;
956	}
