958	HcclResult ParseRetryEnable()
959	{
960	    // 默认都设置成false
961	    for (u32 level = 0; level < HCCL_RETRY_ENABLE_LEVEL_NUM; ++level) {
962	        g_algEnvConfig.hcclRetryConfig[level] = false;
963	    }
964	    std::string hcclRetryEnable = GetEnv("HCCL_OP_RETRY_ENABLE");
965	    if (hcclRetryEnable == "EmptyString") {
966	        HCCL_INFO("[ParseRetryEnable] HCCL_OP_RETRY_ENABLE is not set. The retryEnable of all levels is set to false.");
967	        return HCCL_SUCCESS;
968	    }
969	    // 去除空格
970	    std::string retryConfig = hcclRetryEnable;
971	    retryConfig.erase(std::remove(retryConfig.begin(), retryConfig.end(), ' '), retryConfig.end());
972	
973	    if (retryConfig.empty()) {
974	        HCCL_INFO("[ParseRetryEnable] Hccl retry config is empty. The retryEnable of all levels is set to false.");
975	        return HCCL_SUCCESS;
976	    }
977	
978	    std::vector<std::string> retryEnables;
979	    HcclResult ret = SplitHcclRetryEnable(retryConfig, retryEnables);
980	    CHK_PRT_RET(
981	        ret != HCCL_SUCCESS,
982	        HCCL_ERROR(
983	            "[CollectRetryEnableFromConfig] Hccl retry config[%s] is invalid. "
984	            "expect: L1:0, L2:0",
985	            retryConfig.c_str()),
986	        ret);
987	
988	    CHK_RET(CollectRetryEnableFromConfig(retryEnables));
989	    HCCL_INFO("[ParseRetryEnable] HCCL_OP_RETRY_ENABLE set by environment variable to [%s].", retryConfig.c_str());
990	    return HCCL_SUCCESS;
991	}
