993	HcclResult ParseDeterministic()
994	{
995	    std::string hcclDeterministicEnv = GetEnv("HCCL_DETERMINISTIC");
996	    if (hcclDeterministicEnv == "EmptyString") {
997	        HCCL_INFO("HCCL_DETERMINISTIC set by default to [false]");
998	        return HCCL_SUCCESS;
999	    }
1000	
1001	    std::transform(hcclDeterministicEnv.begin(), hcclDeterministicEnv.end(), hcclDeterministicEnv.begin(), ::toupper);
1002	    if (hcclDeterministicEnv != "STRICT" && hcclDeterministicEnv != "TRUE" && hcclDeterministicEnv != "FALSE") {
1003	        HCCL_ERROR("HCCL_DETERMINISTIC is set to [%s], which is incorrect. Please check", hcclDeterministicEnv.c_str());
1004	        return HCCL_E_PARA;
1005	    }
1006	    if (hcclDeterministicEnv == "STRICT") {
1007	        // 规约保序场景（严格的确定性计算，在确定性的基础上强保证规约顺序一致）
1008	        HcclDevType deviceType;
1009	        CHK_RET(HcclGetDeviceType(deviceType));
1010	        // 规约保序支持A2 A3 A5场景
1011	        bool supportedDevice = false;
1012	        supportedDevice
1013	            = (deviceType == HcclDevType::DEV_TYPE_910B || deviceType == HcclDevType::DEV_TYPE_910_93
1014	               || shouldGoOutPlace(deviceType));
1015	        if (!supportedDevice) {
1016	            HCCL_ERROR(
1017	                "HCCL_DETERMINISTIC is set to [%s], Reduce order preservation is not supported for "
1018	                "deviceType[%d], please check",
1019	                hcclDeterministicEnv.c_str(), deviceType);
1020	            return HCCL_E_NOT_SUPPORT;
1021	        }
1022	        g_algEnvConfig.hcclDeterministic = static_cast<u8>(DeterministicEnableLevel::DETERMINISTIC_STRICT);
1023	    } else if (hcclDeterministicEnv == "TRUE") {
1024	        // 确定性计算场景（不保证规约保序）
1025	        g_algEnvConfig.hcclDeterministic = static_cast<u8>(DeterministicEnableLevel::DETERMINISTIC_ENABLE);
1026	    } else {
1027	        g_algEnvConfig.hcclDeterministic = static_cast<u8>(DeterministicEnableLevel::DETERMINISTIC_DISABLE);
1028	    }
1029	    HCCL_INFO(
1030	        "HCCL_DETERMINISTIC set by environment to [%s], hcclDeterministic[%u]", hcclDeterministicEnv.c_str(),
1031	        g_algEnvConfig.hcclDeterministic);
1032	    return HCCL_SUCCESS;
1033	}
