1035	HcclResult ParseDfsConfig()
1036	{
1037	    std::string dfsConfigEnv = GetEnv("HCCL_DFS_CONFIG");
1038	    if (dfsConfigEnv == "EmptyString") {
1039	        HCCL_INFO("[ParseDfsConfig] HCCL_DFS_CONFIG is not set.");
1040	        return HCCL_SUCCESS;
1041	    }
1042	    dfsConfigEnv.erase(std::remove(dfsConfigEnv.begin(), dfsConfigEnv.end(), ' '), dfsConfigEnv.end());
1043	    std::transform(dfsConfigEnv.begin(), dfsConfigEnv.end(), dfsConfigEnv.begin(), ::tolower);
1044	    auto items = SplitDfsConfig(dfsConfigEnv, ',');
1045	    for (const auto& item : items) {
1046	        auto itemPair = SplitDfsConfig(item, ':');
1047	        constexpr std::size_t ITEM_SIZE = 2;
1048	        if (itemPair.size() != ITEM_SIZE) {
1049	            HCCL_ERROR("[ParseDfsConfig] failed. invalid item[%s]", item.c_str());
1050	            return HCCL_E_PARA;
1051	        }
1052	        if (itemPair[0] == "inconsistent_check") {
1053	            CHK_RET(ParseInconsistentCheckSwitch(itemPair[1]));
1054	        } else if (itemPair[0] == "task_exception") {
1055	            if (itemPair[1] == "off") {
1056	                g_algEnvConfig.taskExceptionEnable = false;
1057	                HCCL_INFO("[ParseDfsConfig] task_exception disabled");
1058	            } else if (itemPair[1] == "on") {
1059	                g_algEnvConfig.taskExceptionEnable = true;
1060	            } else {
1061	                HCCL_ERROR("[ParseDfsConfig] invalid task_exception value[%s]", itemPair[1].c_str());
1062	                return HCCL_E_PARA;
1063	            }
1064	        }
1065	    }
1066	    return HCCL_SUCCESS;
1067	}
