1069	std::vector<std::string> SplitDfsConfig(const std::string& str, char delimiter)
1070	{
1071	    std::vector<std::string> tokens;
1072	    std::istringstream stream(str);
1073	    std::string token;
1074	
1075	    while (std::getline(stream, token, delimiter)) {
1076	        tokens.push_back(token);
1077	    }
1078	    if (stream.peek() != EOF) {
1079	        std::string remaining;
1080	        std::getline(stream, remaining);
1081	        tokens.push_back(remaining);
1082	    }
1083	    if (!str.empty() && str.back() == delimiter) {
1084	        tokens.push_back("");
1085	    }
1086	    return tokens;
1087	}
