1089	HcclResult ParseInconsistentCheckSwitch(const std::string& inconsistentCheckSwitch)
1090	{
1091	    if (inconsistentCheckSwitch == "on") {
1092	        g_algEnvConfig.inconsistentCheckSwitch = 1;
1093	    } else if (inconsistentCheckSwitch == "first") {
