181	    const TopoInfoWithNetLayerDetails* topoInfo, const u32 netLayer, const CommTopo topoType) const
182	{
183	    CHK_PRT_RET(
184	        topoInfo->netLayerDetails.localNetInsSizeOfLayer.size() <= netLayer,
185	        HCCL_WARNING(
186	            "[BaseSelector][IsLayerAllConnetedWithTopo] localNetInsSizeOfLayer size[%u] <= netLayer[%u]",
187	            topoInfo->netLayerDetails.localNetInsSizeOfLayer.size(), netLayer),
188	        false);
189	    u32 localRankSize = topoInfo->netLayerDetails.localNetInsSizeOfLayer[netLayer];
190	
191	    CHK_PRT_RET(
192	        topoInfo->topoInstDetailsOfLayer.size() <= netLayer,
193	        HCCL_WARNING(
194	            "[BaseSelector][IsLayerAllConnetedWithTopo] topoInstDetailsOfLayer size[%u] <= netLayer[%u]",
195	            topoInfo->topoInstDetailsOfLayer.size(), netLayer),
196	        false);
197	
198	    auto rankNumForTopoTypeItr = topoInfo->topoInstDetailsOfLayer[netLayer].rankNumForTopoType.find(topoType);
199	    if (rankNumForTopoTypeItr == topoInfo->topoInstDetailsOfLayer[netLayer].rankNumForTopoType.end()) {
200	        return false;
201	    }
202	
203	    for (auto topoRankNum : rankNumForTopoTypeItr->second) {
204	        if (topoRankNum == localRankSize) {
205	            return true;
206	        }
207	    }
208	    return false;
