240	    // 检查topoInstDetails是否为空
241	    CHK_PRT_RET(
242	        topoInstDetails.empty(),
243	        HCCL_ERROR("[BaseSelector][CheckClosNumMultipleOfMeshNum] topoInstDetailsOfLayer0 size is zero."),
244	        HCCL_E_INTERNAL);
245	
246	    const auto& rankNumMap = topoInstDetails[0].rankNumForTopoType;
247	    auto closItr = rankNumMap.find(COMM_TOPO_CLOS);
248	    auto meshItr = rankNumMap.find(COMM_TOPO_1DMESH);
249	    CHK_PRT_RET(
250	        closItr == rankNumMap.end() || closItr->second.empty() || meshItr == rankNumMap.end()
251	            || meshItr->second.empty(),
252	        HCCL_ERROR("[BaseSelector][CheckClosNumMultipleOfMeshNum] topoInstDetailsOfLayer0 size is zero."),
253	        HCCL_E_INTERNAL);
254	
255	    // 获取CLOS和1DMESH拓扑的rank数量
256	    const auto closRankNums = closItr->second[0];
257	    const auto meshRankNums = meshItr->second[0];
258	
259	    // 检查CLOS数量是否大于1DMESH数量且是1DMESH数量的倍数
260	    isMultiple = (meshRankNums > 1) && (closRankNums > meshRankNums) && (closRankNums % meshRankNums == 0);
261	    return HCCL_SUCCESS;
262	}
