264	bool AutoSelectorBase::IsTwoLevelNetLayer(const TopoInfoWithNetLayerDetails* topoInfo, const OpParam& opParam) const
265	{
266	    CHK_PRT_RET(
267	        topoInfo == nullptr, HCCL_WARNING("[AutoSelectorBase][IsTwoLevelNetLayer] topoInfo is nullptr."), false);
268	    // hostDPU场景不走二级网络算法
269	    bool hostDPUOnly = false;
270	    if ((CheckHostDPUOnly(opParam.hcclComm, topoInfo, hostDPUOnly) == HCCL_SUCCESS) && hostDPUOnly) {
271	        HCCL_INFO("[AutoSelectorBase][IsTwoLevelNetLayer] host DPU only, not two level net layer.");
272	        return false;
273	    }
274	    if (topoInfo->netLayerDetails.netLayerNum <= 1) {
275	        HCCL_INFO(
276	            "[AutoSelectorBase][IsTwoLevelNetLayer] netLayerNum[%u] <= 1, not two level net layer.",
277	            topoInfo->netLayerDetails.netLayerNum);
278	        return false;
279	    }
280	    u32 level1Idx = topoInfo->netLayerDetails.netLayers[1];
281	    bool hasLevel1Clos = topoInfo->topoInstDetailsOfLayer.size() > level1Idx
282	                         && topoInfo->topoInstDetailsOfLayer[level1Idx].rankNumForTopoType.find(COMM_TOPO_CLOS)
283	                                != topoInfo->topoInstDetailsOfLayer[level1Idx].rankNumForTopoType.end();
284	    if (!hasLevel1Clos) {
285	        HCCL_INFO(
286	            "[AutoSelectorBase][IsTwoLevelNetLayer] level1[%u] has no CLOS topo, not two level net layer.", level1Idx);
287	        return false;
288	    }
289	    if (topoInfo->netLayerDetails.localNetInsSizeOfLayer.size() < 1
290	        || topoInfo->netLayerDetails.localNetInsSizeOfLayer[0] <= 1) {
291	        HCCL_INFO(
292	            "[AutoSelectorBase][IsTwoLevelNetLayer] level0 localNetInsSizeOfLayer[%zu] <= 1, not two level net layer.",
293	            topoInfo->netLayerDetails.localNetInsSizeOfLayer.size());
294	        return false;
295	    }
296	    HCCL_INFO(
297	        "[AutoSelectorBase][IsTwoLevelNetLayer] topoLevelNums[%u], netLayerNum[%u], level0Topo[MESH_1D], "
298	        "level1Idx[%u] has CLOS, level0LocalNetInsSize[%u], is two level net layer.",
299	        topoInfo->topoLevelNums, topoInfo->netLayerDetails.netLayerNum, level1Idx,
300	        topoInfo->netLayerDetails.localNetInsSizeOfLayer[0]);
301	    return true;
302	}
